// @generated by the slice schematic 1.2.0 from its spec. Edit in place; reshape via the spec and --force.
import { Injectable, computed, inject, signal } from '@angular/core';
import type { BadgeVariants } from '@spartan-ng/helm/badge';
import { BookService } from '../book/book.service';
import type { BookFormModel } from '../book/book.schema';

type BadgeVariant = NonNullable<BadgeVariants['variant']>;

/** Every piece of spec text the screen shows. The template binds to these and never repeats them. */
const BOOKS_TEXT = {
  title: 'Books',
  plural: 'books',
  createLabel: 'Add book',
  createTitle: 'Create book',
  createDescription: 'Add a new book.',
  editTitle: 'Edit book',
  editDescription: "Change this book's details and save.",
  deleteTitle: 'Delete book?',
  deleteDescription: 'This book will be permanently removed. This cannot be undone.',
  searchLabel: 'Search books',
  searchPlaceholder: 'Search books...',
  empty: 'No books match this filter.',
  edit: 'Edit',
  delete: 'Delete',
  actions: 'Actions',
  all: 'All',
  sortedBy: 'sorted by popularity index',
  filters: {
    genre: 'Genre',
  },
  columns: {
    title: 'Book Title',
    author: 'Author',
    genre: 'Genre',
    popularity: 'Popularity Index',
    availability: 'Availability',
    condition: 'Condition',
  },
} as const;

const AVAILABILITY_VARIANTS: Readonly<Record<string, BadgeVariant>> = {
  Available: 'default',
  Reserved: 'outline',
  Lost: 'destructive',
};

@Injectable()
export class BooksViewModel {
  private readonly bookService = inject(BookService);

  readonly text = BOOKS_TEXT;
  readonly books = this.bookService.books;

  readonly searchQuery = signal('');
  readonly genreFilter = signal('');

  readonly genreFilterOptions: ReadonlyArray<{ value: string; label: string }> = [
    { value: '', label: BOOKS_TEXT.all },
    { value: 'Fiction', label: 'Fiction' },
    { value: 'Mystery', label: 'Mystery' },
    { value: 'Science', label: 'Science' },
    { value: 'History', label: 'History' },
    { value: 'Biography', label: 'Biography' },
    { value: 'Fantasy', label: 'Fantasy' },
    { value: 'Children', label: 'Children' },
  ];

  readonly genreFilterLabel = (value: string): string =>
    this.genreFilterOptions.find((o) => o.value === value)?.label ?? '';

  /** The id of the book being edited, '' for a new one, or null when closed. */
  readonly editing = signal<string | null>(null);

  readonly filtered = computed(() => {
    const q = this.searchQuery().toLowerCase();
    const genreSelected = this.genreFilter();
    const rows = this.books()
      .filter((item) => !genreSelected || item.genre === genreSelected)
      .filter(
        (item) =>
          !q || item.title.toLowerCase().includes(q) || item.author.toLowerCase().includes(q),
      );
    return [...rows].sort((a, b) => (a.popularity - b.popularity) * -1);
  });

  readonly editingBook = computed(() => {
    const id = this.editing();
    return id ? this.bookService.byId(id) : undefined;
  });

  readonly availabilityVariant = (value: string): BadgeVariant =>
    AVAILABILITY_VARIANTS[value] ?? 'secondary';

  startCreate(): void {
    this.editing.set('');
  }

  startEdit(id: string): void {
    this.editing.set(id);
  }

  cancel(): void {
    this.editing.set(null);
  }

  save(model: BookFormModel): void {
    const id = this.editing();
    if (id) {
      this.bookService.update(id, model);
    } else {
      this.bookService.create(model);
    }
    this.editing.set(null);
  }

  remove(id: string): void {
    this.bookService.remove(id);
    if (this.editing() === id) this.editing.set(null);
  }
}
